/**
 * Verify that requests to websites with SNI fail on jdk 1.6
 * <p/>
 * read for more details:
 * http://en.wikipedia.org/wiki/Server_Name_Indication
 *
 * Test is ignored independent from others as it requires JDK 1.6
 * @throws Exception
 */
@Test
public void testSNIFail() throws Exception {
    assertThrows(IOException.class, () -> Jsoup.connect(WEBSITE_WITH_SNI).execute());
}
}

@Test
public void bodyAfterParseThrowsValidationError_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Connection.Response res = Jsoup.connect(echoUrl).execute(); Document doc = res.parse(); String body = res.body(); });
}

@Test
public void parseParseThrowsValidates_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Connection.Response res = Jsoup.connect(echoUrl).execute(); Document doc = res.parse(); assertTrue(doc.title().contains("Environment")); Document doc2 = res.parse(); // should blow up because the response input stream has been drained });
}
}

